class Solution {
  private static int[] colors(int[][] edges) {
    int n = edges.length + 1;
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int[] col = new int[n], queue = new int[n];
    java.util.Arrays.fill(col, -1);
    col[0] = 0;
    int head = 0, tail = 0;
    queue[tail++] = 0;
    while (head < tail) {
      int u = queue[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        if (col[to[p]] < 0) {
          col[to[p]] = col[u] ^ 1;
          queue[tail++] = to[p];
        }
      }
    }
    return col;
  }

  public int[] maxTargetNodes(int[][] edges1, int[][] edges2) {
    int[] c1 = colors(edges1), c2 = colors(edges2);
    int[] cnt1 = new int[2], cnt2 = new int[2];
    for (int c : c1) cnt1[c]++;
    for (int c : c2) cnt2[c]++;
    int best = Math.max(cnt2[0], cnt2[1]);
    int[] ans = new int[c1.length];
    for (int i = 0; i < ans.length; i++) ans[i] = cnt1[c1[i]] + best;
    return ans;
  }
}
